insert into public.products (id, shopify_id, handle, title, original_title, type, category_id, collections, is_new, is_best_seller, vendor, description, price_min, price_max, in_stock, original_url) values ('6f61fbfd-0f6e-5ca1-bd15-adcc8f9555e1', 7901533241427, '6-seater-dining-set', '6 Seater Dining Set', '6 SEATER DINING SET', 'Tables', '9a664795-c07e-5b10-97a0-ff9432053fe8', '{"bedroom"}'::text[], false, false, 'Modern Furniture Pacific', 'Here is a professional website-ready product description you can use for the dining set in the image: Elegant 6-Seater Solid Wood Dining Set Upgrade your dining space with this beautifully crafted 6-seater solid wood dining set, designed to combine durability, comfort, and timeless style. The spacious rectangular table provides ample room for family meals, gatherings, and entertaining guests, while the six ergonomically designed chairs offer excellent back support and cushioned seating for added comfort. Finished in a rich dark wood tone, this dining set complements both modern and classic interiors. Its sturdy construction ensures long-lasting performance, making it a perfect centerpiece for your dining room. Key Features: 6-Seater Dining Set – Ideal for family dining and entertaining Premium Solid Wood Construction – Strong, durable, and long-lasting Comfortable Cushioned Chairs – Soft upholstered seats with supportive backs Elegant Dark Finish – Adds warmth and sophistication to any dining space Spacious Tabletop – Perfect for meals, gatherings, and everyday use Bring style, comfort, and functionality to your home with this modern yet timeless dining set, designed to make every meal a special experience.', 120000, 120000, true, 'https://www.modernfurniturepacificltd.com/products/6-seater-dining-set') on conflict (handle) do update set shopify_id = excluded.shopify_id, title = excluded.title, original_title = excluded.original_title, type = excluded.type, category_id = excluded.category_id, collections = excluded.collections, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, vendor = excluded.vendor, description = excluded.description, price_min = excluded.price_min, price_max = excluded.price_max, in_stock = excluded.in_stock, original_url = excluded.original_url, updated_at = now();
