insert into public.products (id, shopify_id, handle, title, original_title, type, category_id, collections, is_new, is_best_seller, vendor, description, price_min, price_max, in_stock, original_url) values ('bcad875e-506c-5634-9452-12928b5252b4', 7906658353235, '6x6-pacific-pocker-spring-mattress', '6x6 Pacific Pocket Spring Mattress', '6x6 PACIFIC  POCKER SPRING MATTRESS', 'Bed', '0f9a11d6-d9f2-5a98-b33e-d723fa71a98d', '{"bedroom-1"}'::text[], false, false, 'Modern Furniture Pacific', '• Individual Support: Unlike traditional spring mattresses where the springs are all connected, pocket springs are each housed in their own fabric pocket. This allows them to move independently, contouring to your body and providing support right where you need it. This is great for maintaining good posture while you sleep.  • No More Bouncing: A big plus for pocket spring mattresses is that they reduce motion transfer. So, if you share your bed, you''re less likely to be disturbed when your partner tosses and turns.  • Durability: These mattresses are often marketed as being very durable. In fact, one promotion for the Pacific Mattress brand showed a car driving over one to demonstrate its resilience!  • Comfort Options: While details for this specific mattress aren''t available, similar mattresses from other brands in Kenya are often advertised with orthopedic support and sometimes even have a 2-in-1 design with a soft side and a firm side. The Pacific Mattress itself is promoted as offering a "perfect sleep" with a seven-year warranty. ', 23000, 37000, true, 'https://www.modernfurniturepacificltd.com/products/6x6-pacific-pocker-spring-mattress') on conflict (handle) do update set shopify_id = excluded.shopify_id, title = excluded.title, original_title = excluded.original_title, type = excluded.type, category_id = excluded.category_id, collections = excluded.collections, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, vendor = excluded.vendor, description = excluded.description, price_min = excluded.price_min, price_max = excluded.price_max, in_stock = excluded.in_stock, original_url = excluded.original_url, updated_at = now();
