insert into public.products (id, shopify_id, handle, title, original_title, type, category_id, collections, is_new, is_best_seller, vendor, description, price_min, price_max, in_stock, original_url) values ('ae60c687-ca56-5458-bf4b-42bb21410139', 7902684282963, 'cozy-sofa', 'Cozy Sofa', 'COZY SOFA', 'Sofa', '16fea79e-6bd6-557b-8dd3-195917664396', '{"living-room"}'::text[], false, false, 'Modern Furniture Pacific', 'Modern L-Shaped Sectional Sofa with Wooden Side Shelves Upgrade your living space with this stylish and spacious L-shaped sectional sofa designed for both comfort and elegance. Upholstered in soft, high-quality fabric, this sofa features plush cushions and a deep seating design that provides exceptional relaxation for family and guests. The contemporary design is complemented by built-in wooden side shelves, perfect for placing books, décor, or everyday essentials, adding both functionality and sophistication to your living room. Its sturdy wooden base ensures durability while the neutral color easily blends with different interior styles. Perfect for large living rooms, lounges, or modern homes, this sectional sofa offers the ideal combination of luxury, comfort, and practicality. Key Features: Spacious L-shaped sectional design Soft, durable fabric upholstery Comfortable high-density cushions Elegant wooden side shelves for storage Strong wooden base for durability Modern design suitable for contemporary homes ✨ A perfect centerpiece for a modern and comfortable living room.', 200000, 200000, false, 'https://www.modernfurniturepacificltd.com/products/cozy-sofa') on conflict (handle) do update set shopify_id = excluded.shopify_id, title = excluded.title, original_title = excluded.original_title, type = excluded.type, category_id = excluded.category_id, collections = excluded.collections, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, vendor = excluded.vendor, description = excluded.description, price_min = excluded.price_min, price_m