insert into public.products (id, shopify_id, handle, title, original_title, type, category_id, collections, is_new, is_best_seller, vendor, description, price_min, price_max, in_stock, original_url) values ('fda5ba38-7909-5e4c-bbaf-bcc420214fb1', 7902006083667, 'juventus-sofa-set', 'Juventus Sofa Set', 'JUVENTUS SOFA SET', 'Living Room', '16fea79e-6bd6-557b-8dd3-195917664396', '{}'::text[], false, false, 'Modern Furniture Pacific', 'Premium Product Description Experience comfort and modern elegance with this beautifully crafted modern grey sofa set. Designed with plush cushioning, wide armrests, and a sturdy wooden base, it offers the perfect balance of style and durability. The spacious seating and matching chaise lounge make it ideal for relaxing, entertaining guests, or elevating the look of your living room. A perfect choice for those who love contemporary luxury and comfort. 2. Short Social Media Caption Upgrade your living space with this luxurious modern grey sofa set 🛋️ ✔ Spacious & comfortable ✔ Elegant wooden finish ✔ Perfect for modern homes Style meets comfort in every seat. 3. Sales-Focused Description Transform your home with this stylish and ultra-comfortable sofa set. Featuring soft premium fabric, supportive back cushions, and a durable wooden frame, this set is built for both relaxation and long-lasting quality. Its sleek modern design adds a sophisticated touch to any living room. Modern design. Ultimate comfort. Timeless elegance. 🛋️ This stunning grey sofa set with wooden accents is the perfect centerpiece for a stylish and cozy living room.', 45000, 110000, true, 'https://www.modernfurniturepacificltd.com/products/juventus-sofa-set') on conflict (handle) do update set shopify_id = excluded.shopify_id, title = excluded.title, original_title = excluded.original_title, type = excluded.type, category_id = excluded.category_id, collections = excluded.collections, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, vendor = excluded.v