insert into public.products (id, shopify_id, handle, title, original_title, type, category_id, collections, is_new, is_best_seller, vendor, description, price_min, price_max, in_stock, original_url) values ('77ce6896-dbf3-544f-adf3-b4902d6f0224', 7902642569299, 'urban-nest-sofa-set', 'Urban Nest Sofa Set', 'URBAN NEST SOFA SET', 'Sofa', '16fea79e-6bd6-557b-8dd3-195917664396', '{}'::text[], false, false, 'Modern Furniture Pacific', 'Elegant Single-Seater Lounge Chairs – Comfort Meets Modern Style Upgrade your living space with these beautifully designed single-seater lounge chairs from Modern Furniture Pacific. Crafted with a sleek modern silhouette, these chairs feature plush cushioning, supportive armrests, and durable upholstery that offers both comfort and long-lasting quality. The neutral two-tone fabric blends effortlessly with different interior styles, making them perfect for living rooms, offices, lounges, or reception areas. Supported by sturdy metal legs, the chairs provide stability while adding a contemporary touch to your space. Whether you''re creating a cozy reading corner or stylish seating for guests, these lounge chairs deliver both sophistication and relaxation. Key Features: • Soft, high-density cushioning for superior comfort • Durable, easy-to-maintain fabric upholstery • Modern two-tone design for a stylish look • Strong metal legs for stability and durability • Ideal for living rooms, offices, and reception areas Modern Furniture Pacific – Hammering wood Your Style. ✨', 25000, 90000, true, 'https://www.modernfurniturepacificltd.com/products/urban-nest-sofa-set') on conflict (handle) do update set shopify_id = excluded.shopify_id, title = excluded.title, original_title = excluded.original_title, type = excluded.type, category_id = excluded.category_id, collections = excluded.collections, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, vendor = excluded.vendor, description = excluded.description, price_min = excluded.price_min, price_max = excluded.price_max, in_stock = excluded.in_stock, original_url = excluded.original_url, updated_at = now();
